import{_ as e,o as i,c as l,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Визиты и магазин","description":"","frontmatter":{"pageId":"players/visits","contentRevision":5},"headers":[],"relativePath":"ru/players/visits.md","filePath":"ru/players/visits.md"}'),r={name:"ru/players/visits.md"};function s(o,a,n,d,h,p){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="визиты-и-магазин" tabindex="-1">Визиты и магазин <a class="header-anchor" href="#визиты-и-магазин" aria-label="Permalink to &quot;Визиты и магазин&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Выбери посещение поселения с карты, через караван или доступную кнопку. В обычном визите загружается копия чужой карты, а не текущая авторитетная симуляция хозяина. Гостевые пешки остаются гостевыми; используй кнопку завершения визита для возвращения.</p><p>Обычные вещи из посещённой копии нельзя просто забрать домой. Разрешённый обмен идёт через магазин хозяина и серверные операции: покупка оплачивается кошельком и учитывается отдельно от состояния копии.</p><p>Если нужен совместный бой в реальном времени, выбирай live-визит и дождись согласия хозяина. Это другой режим с другим протоколом возврата и подключения.</p><h2 id="visit-flow" tabindex="-1">Обычный визит и покупка с полки <a class="header-anchor" href="#visit-flow" aria-label="Permalink to &quot;Обычный визит и покупка с полки {#visit-flow}&quot;">​</a></h2><ol><li>На чужом поселении выбери «Visit» караваном/капсулами, не «Real raid» и не live.</li><li>Домашняя колония сохраняется. Загружается копия карты хозяина с копиями твоих пешек; отсутствие хозяина online не запускает его настоящую карту.</li><li>Осмотри поселение. Просто поднятые с земли предметы не переносятся домой. Покупай только помеченное хозяином «For sale» через кнопку Buy, за кошелёк.</li><li>«End visit» возвращает домашнюю карту. Покупки придут туда серверными посылками.</li></ol><p>Чтобы продавать у себя, выдели предмет → «For sale…», укажи цену и сохранись: полка публикуется с сейвом. Проданные вещи убираются из твоих запасов при следующем входе. Это отдельный механизм от обычного лота в глобальном рынке.</p><h2 id="visit-load" tabindex="-1">Если карта визита не загружается <a class="header-anchor" href="#visit-load" aria-label="Permalink to &quot;Если карта визита не загружается {#visit-load}&quot;">​</a></h2><p>У хозяина может быть мод или DLC, которого нет у тебя; сверка должна остановить вход до загрузки и назвать зависимости. Не удаляй XML-объекты из чужого сейва ради входа. Если продавец отключил визиты или ещё не имеет колонии, нужно другое действие, не принудительная загрузка копии.</p><p>При возвращении проверь домашнюю карту и почту. Копия визита не должна сохраняться поверх домашней. Для живого взаимодействия попроси live-визит — там нужны online хозяин, согласие и отдельные правила возврата реальных гостевых пешек.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>По умолчанию визит ограничен 12 часами. Не подменяй домашний сейв посещённой копией. Блокировка сообщений сама по себе не запрещает посещение.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./live">Live: живая карта</a></li><li><a href="./economy">Кошелёк, почта и рынок</a></li><li><a href="./saves-recovery">Сохранения и восстановление</a></li></ul>',16)])])}const v=e(r,[["render",s]]);export{u as __pageData,v as default};
